const d = $input.first().json;
const text = (key) => String(d[key] ?? '').trim();
const headline = text('headline');
const summary = text('verifiedSummary');
const videoUrl = text('videoUrl');
const sourceUrl = text('sourceUrl');
const language = text('language') || 'French';
const rights = text('videoRights');
const approved = text('editorApproval');
if (rights !== 'Yes - I have publishing rights') {
  throw new Error('STOP: The video cannot be posted without confirmed redistribution rights.');
}
if (approved !== 'Yes - editor approved') {
  throw new Error('STOP: A human editor must approve the factual claims and video before publishing.');
}
if (!headline || !summary || !sourceUrl || !videoUrl) {
  throw new Error('Headline, verified summary, original source, and video URL are required.');
}
for (const [label, url] of [['Video', videoUrl], ['Source', sourceUrl]]) {
  let parsed;
  try { parsed = new URL(url); } catch { throw new Error(label + ' URL is invalid.'); }
  if (parsed.protocol !== 'https:' || !parsed.hostname || parsed.username || parsed.password) {
    throw new Error(label + ' URL must be a public HTTPS link without credentials.');
  }
}
if (summary.length < 40) throw new Error('Provide at least 40 characters of checked facts.');
if (headline.length > 110) throw new Error('Shorten the headline to 110 characters.');
return [{json:{headline,summary,videoUrl,sourceUrl,language,brand:'Inside Mauritius',approved:true}}];

const source = $('Check Permissions & Facts').first().json;
const result = $input.first().json;
let content = result?.choices?.[0]?.message?.content;
if (Array.isArray(content)) content = content.map(x => x.text || '').join('');
if (typeof content !== 'string') throw new Error('OpenAI returned no usable response.');
let v;
try { v = JSON.parse(content); } catch { throw new Error('AI returned invalid JSON. Please rerun.'); }
const fallback = source.headline;
const clip = (value,max) => String(value || '').trim().slice(0,max);
const youtubeTitle = clip(v.youtube_title || fallback,95);
const description = clip(v.youtube_description || source.summary,4000);
const tiktok = clip(v.tiktok_caption || fallback,1200);
const instagram = clip(v.instagram_caption || fallback,1600);
const facebook = clip(v.facebook_caption || fallback,1800);
if (!youtubeTitle || !description || !tiktok || !instagram || !facebook) throw new Error('AI output incomplete.');
return [{json:{...source,youtubeTitle,youtubeDescription:description,tiktokCaption:tiktok,instagramCaption:instagram,facebookCaption:facebook,preparedAt:new Date().toISOString()}}];

const upstream = $('Prepare Platform Captions').first().json;
const response = $input.first().json;
return [{json:{status:'SUBMITTED_TO_PUBLISHER_NOT_YET_VERIFIED_LIVE',brand:'Inside Mauritius',headline:upstream.headline,videoUrl:upstream.videoUrl,sourceUrl:upstream.sourceUrl,publisherResponse:response,notice:'Check your Upload-Post account for publishing status and failures before announcing that the posts are live.'}}];
